            t_qq1_r_aa_201 = x51
            qq1_r_aa(3, 1, 2) = qq1_r_aa(3, 1, 2) + t_qq1_r_aa_201
            qq1_r_aa(3, 2, 1) = qq1_r_aa(3, 2, 1) + t_qq1_r_aa_201
            t_qq1_r_aa_202 = x55
            qq1_r_aa(3, 1, 3) = qq1_r_aa(3, 1, 3) + t_qq1_r_aa_202
            qq1_r_aa(3, 3, 1) = qq1_r_aa(3, 3, 1) + t_qq1_r_aa_202
            qq1_r_aa(3, 2, 2) = qq1_r_aa(3, 2, 2) + (x58)
            t_qq1_r_aa_212 = x59
            qq1_r_aa(3, 2, 3) = qq1_r_aa(3, 2, 3) + t_qq1_r_aa_212
            qq1_r_aa(3, 3, 2) = qq1_r_aa(3, 3, 2) + t_qq1_r_aa_212
            qq1_r_aa(3, 3, 3) = &
               qq1_r_aa(3, 3, 3) + (-3.0_wp*x17 + x23*x61 - x28*x61 + x29*x60 + 3.0_wp*x38)
            qq2_rr_aa(1, 1, 1, 1) = &
               qq2_rr_aa(1, 1, 1, 1) + (x23*x65 - x28*x65 + 6.0_wp*x30 + x63*x64 - x63*x68 - &
               x66*x67 + x66*x69 + x70)
            t_qq2_rr_aa_0001 = x78
            qq2_rr_aa(1, 1, 1, 2) = qq2_rr_aa(1, 1, 1, 2) + t_qq2_rr_aa_0001
