            t_qq2_rr_aa_0002 = x84
            qq2_rr_aa(1, 1, 1, 3) = qq2_rr_aa(1, 1, 1, 3) + t_qq2_rr_aa_0002
            qq2_rr_aa(1, 1, 3, 1) = qq2_rr_aa(1, 1, 3, 1) + t_qq2_rr_aa_0002
            qq2_rr_aa(1, 1, 2, 2) = qq2_rr_aa(1, 1, 2, 2) + (x94)
            t_qq2_rr_aa_0012 = x97
            qq2_rr_aa(1, 1, 2, 3) = qq2_rr_aa(1, 1, 2, 3) + t_qq2_rr_aa_0012
            qq2_rr_aa(1, 1, 3, 2) = qq2_rr_aa(1, 1, 3, 2) + t_qq2_rr_aa_0012
            qq2_rr_aa(1, 1, 3, 3) = qq2_rr_aa(1, 1, 3, 3) + (x100)
            t_qq2_rr_aa_0100 = x78
            qq2_rr_aa(1, 2, 1, 1) = qq2_rr_aa(1, 2, 1, 1) + t_qq2_rr_aa_0100
            qq2_rr_aa(2, 1, 1, 1) = qq2_rr_aa(2, 1, 1, 1) + t_qq2_rr_aa_0100
            t_qq2_rr_aa_0101 = x94
            qq2_rr_aa(1, 2, 1, 2) = qq2_rr_aa(1, 2, 1, 2) + t_qq2_rr_aa_0101
            qq2_rr_aa(1, 2, 2, 1) = qq2_rr_aa(1, 2, 2, 1) + t_qq2_rr_aa_0101
            qq2_rr_aa(2, 1, 1, 2) = qq2_rr_aa(2, 1, 1, 2) + t_qq2_rr_aa_0101
            qq2_rr_aa(2, 1, 2, 1) = qq2_rr_aa(2, 1, 2, 1) + t_qq2_rr_aa_0101
            t_qq2_rr_aa_0102 = x97
            qq2_rr_aa(1, 2, 1, 3) = qq2_rr_aa(1, 2, 1, 3) + t_qq2_rr_aa_0102
            qq2_rr_aa(1, 2, 3, 1) = qq2_rr_aa(1, 2, 3, 1) + t_qq2_rr_aa_0102
            qq2_rr_aa(2, 1, 1, 3) = qq2_rr_aa(2, 1, 1, 3) + t_qq2_rr_aa_0102
            qq2_rr_aa(2, 1, 3, 1) = qq2_rr_aa(2, 1, 3, 1) + t_qq2_rr_aa_0102
            t_qq2_rr_aa_0111 = x103
            qq2_rr_aa(1, 2, 2, 2) = qq2_rr_aa(1, 2, 2, 2) + t_qq2_rr_aa_0111
            qq2_rr_aa(2, 1, 2, 2) = qq2_rr_aa(2, 1, 2, 2) + t_qq2_rr_aa_0111
            t_qq2_rr_aa_0112 = x105
            qq2_rr_aa(1, 2, 2, 3) = qq2_rr_aa(1, 2, 2, 3) + t_qq2_rr_aa_0112
            qq2_rr_aa(1, 2, 3, 2) = qq2_rr_aa(1, 2, 3, 2) + t_qq2_rr_aa_0112
            qq2_rr_aa(2, 1, 2, 3) = qq2_rr_aa(2, 1, 2, 3) + t_qq2_rr_aa_0112
